/**
 * The curated model list shipped with the app (generated by `npm run update:models` from
 * LiteLLM's public metadata; see scripts/update-model-catalog.ts). Pure lookups only.
 */
import catalogJson from './modelCatalog.json';
import { AiModelOption, AiProviderId } from '../../types/ai';

export interface CatalogEntry {
  id: string;
  name: string;
  maxInputTokens?: number;
  maxOutputTokens?: number;
  deprecationDate?: string;
  reasoning?: boolean;
}

export interface ModelCatalogData {
  generatedAt: string;
  source: string;
  providers: Record<AiProviderId, CatalogEntry[]>;
}

export const MODEL_CATALOG: ModelCatalogData = catalogJson as ModelCatalogData;

/**
 * Turns catalog entries into picker options with exactly one `isDefault`:
 * the `preferredId` when present, else the first entry matching `fallback`, else the first entry.
 */
export function toModelOptions(
  entries: CatalogEntry[],
  preferredId?: string,
  fallback: (entry: CatalogEntry) => boolean = () => true
): AiModelOption[] {
  const defaultId =
    entries.find((e) => e.id === preferredId)?.id ?? entries.find(fallback)?.id ?? entries[0]?.id;
  return entries.map((e) => {
    const option: AiModelOption = { id: e.id, name: e.name };
    if (e.maxInputTokens !== undefined) option.maxInputTokens = e.maxInputTokens;
    if (e.maxOutputTokens !== undefined) option.maxOutputTokens = e.maxOutputTokens;
    if (e.deprecationDate) option.deprecationDate = e.deprecationDate;
    if (e.reasoning) option.reasoning = true;
    if (e.id === defaultId) option.isDefault = true;
    return option;
  });
}

export function getDefaultModelId(models: AiModelOption[]): string {
  return models.find((m) => m.isDefault)?.id ?? models[0]?.id ?? '';
}

/** Option label: the name plus a retirement note for models deprecating soon. */
export function formatModelLabel(model: AiModelOption): string {
  return model.deprecationDate ? `${model.name} (retiring ${model.deprecationDate})` : model.name;
}

/** Name fallback for ids the catalog does not know (e.g. a model saved before a refresh). */
const OPENAI_REASONING_ID = /^(o\d+)(?:$|-)|^gpt-(?:[5-9]|\d{2,})(?:$|[.-])/;
const OPENAI_NON_REASONING_ID = /-chat(?:-latest)?$|^gpt-5-chat/;

/**
 * OpenAI reasoning-class models (o-series, GPT-5 and later) reject a non-default `temperature`.
 * The catalog's `reasoning` flag (from LiteLLM's `supports_reasoning`) wins; ids it does not
 * list fall back to a name pattern.
 */
export function isOpenAiReasoningModel(modelId: string, catalog: AiModelOption[] = []): boolean {
  const known = catalog.find((m) => m.id === modelId);
  if (known) return known.reasoning === true;
  return OPENAI_REASONING_ID.test(modelId) && !OPENAI_NON_REASONING_ID.test(modelId);
}

export interface PickerOption {
  id: string;
  label: string;
  /** The saved model, kept selectable although the list no longer offers it. */
  missing?: boolean;
}

/**
 * Picker options for `selectedId`. A selected id that is not in `models` is prepended as
 * "<id> (saved, not in list)" so the picker never silently shows a different model than
 * the one that will actually be sent.
 */
export function buildPickerOptions(
  models: AiModelOption[],
  selectedId: string
): { options: PickerOption[]; selectedMissing: boolean } {
  const options: PickerOption[] = models.map((m) => ({ id: m.id, label: formatModelLabel(m) }));
  const selectedMissing = Boolean(selectedId) && !models.some((m) => m.id === selectedId);
  if (selectedMissing) {
    options.unshift({ id: selectedId, label: `${selectedId} (saved, not in list)`, missing: true });
  }
  return { options, selectedMissing };
}
